// Some portions generated by Claude

// @ts-check
const { test, expect } = require('@playwright/test');
const {
	deleteRepository,
	evidencePath,
	evidenceScreenshots,
	memoryRepositoryConfiguration,
	openQueryPage,
	repositoryPageUrl,
	runQuery,
	serverBaseUrl,
	uniqueRepositoryId,
	waitForRoute
} = require('./workbench-test-helpers.js');

// .agent/execplans/workbench-table-wrap-nquads.md: every Workbench table can wrap its values or keep them on one line
// and scroll sideways, and every table of statements can show them as N-Quads (lines that are never wrapped).
const REPOSITORY_ID = uniqueRepositoryId('workbench-table-wrap');
const EVIDENCE_DIR = process.env.WORKBENCH_TABLE_WRAP_EVIDENCE || '';
const LONG = 'segment-that-keeps-going-for-quite-a-while-without-any-place-to-break-it';
const RESOURCE = `http://example.org/resource/${LONG}`;
const TYPE = `http://example.org/type/${LONG}/${LONG}`;
const GRAPH = `http://example.org/graph/${LONG}/${LONG}`;
const PREDICATE = `http://example.org/property/${LONG}`;
const NAMESPACE = `http://example.org/namespace/${LONG}/${LONG}/`;
const TITLE = `Wrap and N-Quads fixture with a rather long title that ${LONG} ${LONG}`;

const XSD = 'http://www.w3.org/2001/XMLSchema#';
const RDFS_LABEL = 'http://www.w3.org/2000/01/rdf-schema#label';
const RDF_TYPE = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type';

const OUTGOING_LINES = [
	`<${RESOURCE}> <${RDF_TYPE}> <${TYPE}> <${GRAPH}> .`,
	`<${RESOURCE}> <${RDFS_LABEL}> "Said \\"hello\\"\\nand left"@en <${GRAPH}> .`,
	`<${RESOURCE}> <${PREDICATE}> "42"^^<${XSD}integer> <${GRAPH}> .`
];

function fixture() {
	return `<${GRAPH}> {
	<${RESOURCE}> a <${TYPE}> ;
		<${RDFS_LABEL}> "Said \\"hello\\"\\nand left"@en ;
		<${PREDICATE}> 42 .
}
<http://example.org/other> <${PREDICATE}> <${RESOURCE}> .
`;
}

test.describe.configure({ mode: 'serial' });
test.setTimeout(120_000);

test.beforeAll(async ({ request }) => {
	const repositoryUrl = `${serverBaseUrl()}/repositories/${encodeURIComponent(REPOSITORY_ID)}`;
	const created = await request.put(repositoryUrl, {
		headers: { 'Content-Type': 'text/turtle' },
		data: memoryRepositoryConfiguration(REPOSITORY_ID, TITLE)
	});
	expect([200, 201, 204]).toContain(created.status());
	const loaded = await request.post(`${repositoryUrl}/statements`, {
		headers: { 'Content-Type': 'application/trig' },
		data: fixture()
	});
	expect([200, 204], await loaded.text()).toContain(loaded.status());
	const namespace = await request.put(`${repositoryUrl}/namespaces/longns`, {
		headers: { 'Content-Type': 'text/plain' },
		data: NAMESPACE
	});
	expect([200, 204]).toContain(namespace.status());
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

async function screenshot(page, name) {
	if (EVIDENCE_DIR || evidenceScreenshots()) {
		await page.screenshot({ path: evidencePath(EVIDENCE_DIR, `${test.info().project.name}-${name}.png`), fullPage: true });
	}
}

async function pageScrollsSideways(page) {
	return page.evaluate(() => document.scrollingElement.scrollWidth > document.scrollingElement.clientWidth + 1);
}

/** Open a Display disclosure by its toggle id (it may already be open). */
async function openDisplay(page, toggleId) {
	const toggle = page.locator(`#${toggleId}`);
	await expect(toggle).toBeVisible();
	if (await toggle.getAttribute('aria-expanded') !== 'true') {
		await toggle.click();
	}
	await expect(toggle).toHaveAttribute('aria-expanded', 'true');
}

/** The N-Quads lines of a shared result table, and how its box and lines lay out. */
async function nquads(locator) {
	return locator.evaluate((layout) => {
		const box = layout.querySelector(':scope > .query-result-records');
		const lines = Array.from(box.querySelectorAll('.query-result-nquad'));
		return {
			effectiveLayout: layout.getAttribute('data-effective-layout'),
			lines: lines.map(line => line.textContent),
			whiteSpace: lines.length ? getComputedStyle(lines[0]).whiteSpace : '',
			boxScrolls: box.scrollWidth > box.clientWidth + 1 && ['auto', 'scroll'].includes(getComputedStyle(box).overflowX)
		};
	});
}

/** How the cells of a table lay out: one line each or wrapped, and whether the table scrolls in its own box. */
async function tableFlow(table, scroller) {
	return table.evaluate((element, scrollSelector) => {
		const box = scrollSelector ? element.closest(scrollSelector) : element.parentElement;
		const cells = Array.from(element.querySelectorAll('tbody td'));
		return {
			whiteSpace: Array.from(new Set(cells.map(cell => getComputedStyle(cell).whiteSpace))),
			display: getComputedStyle(element).display,
			rowDisplay: getComputedStyle(element.querySelector('tbody tr')).display,
			headVisible: getComputedStyle(element.querySelector('thead')).display !== 'none'
				&& element.querySelector('thead').getBoundingClientRect().height > 1,
			boxScrolls: !!box && box.scrollWidth > box.clientWidth + 1
				&& ['auto', 'scroll'].includes(getComputedStyle(box).overflowX)
		};
	}, scroller);
}

test('Explore shows its statement tables as N-Quads, one whole line per statement', async ({ page }) => {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(`${repositoryPageUrl(REPOSITORY_ID, 'explore')}?resource=${encodeURIComponent(`<${RESOURCE}>`)}`);
	await waitForRoute(page, 'explore');
	const outgoing = page.locator('section.explore-group[data-explore-role="outgoing"] .query-result-layout');
	await expect(outgoing.locator('table.data tbody tr').first()).toBeVisible();

	await openDisplay(page, 'explore-result-options-toggle');
	const layout = page.locator('#explore-result-layout');
	await expect(layout.locator('option')).toHaveText(['Auto', 'Table', 'Records', 'N-Quads']);
	await layout.selectOption('nquads');
	await expect(outgoing).toHaveAttribute('data-effective-layout', 'nquads');
	let shown = await nquads(outgoing);
	expect(shown.lines.slice().sort()).toEqual(OUTGOING_LINES.slice().sort());
	// N-Quads lines are never wrapped, even with Wrap values on: the box scrolls sideways instead.
	await expect(page.locator('#explore-wrap-values')).toBeChecked();
	expect(shown.whiteSpace).toBe('pre');
	expect(shown.boxScrolls, 'whole lines scroll sideways in their box').toBe(true);
	expect(await pageScrollsSideways(page), 'the page itself does not scroll sideways').toBe(false);
	const incoming = page.locator('section.explore-group[data-explore-role="incoming"] .query-result-layout');
	expect((await nquads(incoming)).lines).toEqual([`<http://example.org/other> <${PREDICATE}> <${RESOURCE}> .`]);
	await screenshot(page, 'explore-nquads');

	const wrap = page.locator('#explore-wrap-values');
	await expect(wrap).toBeChecked();
	await wrap.uncheck();
	await expect(outgoing).toHaveAttribute('data-wrap', 'false');
	shown = await nquads(outgoing);
	expect(shown.whiteSpace, 'and with Wrap values off').toBe('pre');
	expect(shown.boxScrolls).toBe(true);

	// The table keeps the chosen wrapping: one line per value, scrolling in its own box.
	await layout.selectOption('table');
	await expect(outgoing).toHaveAttribute('data-effective-layout', 'table');
	const flow = await tableFlow(outgoing.locator('.query-result-table-wrap > table.data'), '.query-result-table-wrap');
	expect(flow.whiteSpace).toEqual(['nowrap']);
	expect(flow.boxScrolls).toBe(true);
	expect(await pageScrollsSideways(page)).toBe(false);

	// The choice holds for the next resource explored.
	// A click outside an open pane closes the pane first.
	await page.locator('#explore-result-options-toggle').click();
	await expect(page.locator('#explore-result-options-panel')).toBeHidden();
	await page.locator('section.explore-group[data-explore-role="incoming"] a[href*="explore?resource="]')
		.filter({ hasText: 'example.org/other' }).first().click();
	await waitForRoute(page, 'explore', {
		url: (url) => url.searchParams.get('resource') === '<http://example.org/other>'
	});
	const next = page.locator('#explore-results .query-result-layout').first();
	await expect(next).toHaveAttribute('data-wrap', 'false');
	await expect(page.locator('#explore-wrap-values')).not.toBeChecked();
	await expect(page.locator('#explore-result-layout')).toHaveValue('table');
});

test('the Export preview offers N-Quads and one-line values', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'export'));
	await waitForRoute(page, 'export');
	await page.locator('#export-preview-form button[type="submit"]').click();
	await waitForRoute(page, 'export', { url: (url) => url.search.length > 0, timeout: 30_000 });
	const preview = page.locator('#export-results .query-result-layout');
	await expect(preview.locator('table.data tbody tr, article.query-result-record').first()).toBeVisible();

	await openDisplay(page, 'export-preview-options-toggle');
	await page.locator('#export-preview-layout').selectOption('nquads');
	await expect(preview).toHaveAttribute('data-effective-layout', 'nquads');
	const shown = await nquads(preview);
	expect(shown.lines).toHaveLength(4);
	for (const line of OUTGOING_LINES) {
		expect(shown.lines).toContain(line);
	}
	expect(shown.lines).toContain(`<http://example.org/other> <${PREDICATE}> <${RESOURCE}> .`);

	await page.locator('#export-preview-layout').selectOption('auto');
	await page.locator('#export-preview-wrap-values').uncheck();
	await expect(preview).toHaveAttribute('data-effective-layout', 'table');
	const flow = await tableFlow(preview.locator('.query-result-table-wrap > table.data'), '.query-result-table-wrap');
	expect(flow.whiteSpace).toEqual(['nowrap']);
	expect(flow.boxScrolls).toBe(true);
	expect(await pageScrollsSideways(page)).toBe(false);
	await screenshot(page, 'export-preview-scroll');
});

