test('the Query page offers N-Quads for statements only', async ({ page }) => {
	await openQueryPage(page, REPOSITORY_ID, { viewport: { width: 1280, height: 900 } });
	await runQuery(page, `CONSTRUCT { ?s ?p ?o } WHERE { GRAPH ?g { ?s ?p ?o } }`);
	const result = page.locator('#query-results');
	const layout = result.locator('select[name="result-layout"]');
	await result.locator('.query-result-options-toggle').click();
	const option = layout.locator('option[value="nquads"]');
	await expect(option).toHaveText('N-Quads');
	await layout.selectOption('nquads');
	const root = result.locator('.query-result-layout').first();
	await expect(root).toHaveAttribute('data-effective-layout', 'nquads');
	// CONSTRUCT results have no graph: three terms per line.
	const constructed = await nquads(root);
	expect(constructed.lines.slice().sort())
		.toEqual(OUTGOING_LINES.map(line => line.replace(` <${GRAPH}> .`, ' .')).sort());
	expect(constructed.whiteSpace, 'N-Quads lines are never wrapped').toBe('pre');
	await screenshot(page, 'query-construct-nquads');

	await runQuery(page, 'SELECT ?s ?p WHERE { ?s ?p ?o } LIMIT 2');
	await expect(root).toHaveAttribute('data-effective-layout', /^(table|records)$/);
	await expect(option, 'a SELECT result offers no N-Quads').toHaveCount(0);
	await expect(layout.locator('option')).toHaveText(['Auto', 'Table', 'Records']);
	await expect(layout).toHaveValue('auto');

	await runQuery(page, `DESCRIBE <${RESOURCE}>`);
	await expect(root, 'a later statement result shows N-Quads again').toHaveAttribute('data-effective-layout', 'nquads');
	await expect(layout).toHaveValue('nquads');
});

const LIST_PAGES = [
	{ kind: 'types', section: '#types-results', text: LONG },
	{ kind: 'contexts', section: '#contexts-results', text: LONG },
	{ kind: 'namespaces', section: '#namespaces-results', text: LONG }
];

for (const width of [1280, 390]) {
	test(`the repositories list has no Display control and wraps its values at ${width} px`, async ({ page }) => {
		await page.setViewportSize({ width, height: 900 });
		await page.goto(repositoryPageUrl(REPOSITORY_ID, 'repositories'));
		await waitForRoute(page, 'repositories');
		const section = page.locator('#repositories-results');
		const table = section.locator('table.data');
		await expect(table).toContainText(TITLE);
		await expect(section).toHaveAttribute('data-table-wrap', 'true');
		await expect(page.locator('#repositories-display-options-toggle'), 'no Display toggle').toHaveCount(0);
		await expect(page.locator('#repositories-wrap-values'), 'no Wrap values checkbox').toHaveCount(0);
		await expect(section.locator('.workbench-table-display'), 'no Display control in the card').toHaveCount(0);
		const flow = await tableFlow(table, '.workbench-table-scroll');
		expect(flow.boxScrolls, 'wrapped values need no sideways scrolling').toBe(false);
		expect(await pageScrollsSideways(page), 'the page itself does not scroll sideways').toBe(false);
		await screenshot(page, `repositories-${width}-wrap`);
	});
}

for (const width of [1280, 390]) {
	for (const list of LIST_PAGES) {
		test(`the ${list.kind} list keeps values on one line and scrolls sideways at ${width} px`, async ({ page }) => {
			await page.setViewportSize({ width, height: 900 });
			await page.goto(repositoryPageUrl(REPOSITORY_ID, list.kind));
			await waitForRoute(page, list.kind);
			const section = page.locator(list.section);
			const table = section.locator('table.data');
			await expect(table).toContainText(list.text);
			await expect(section).toHaveAttribute('data-table-wrap', 'true');
			const wrapped = await tableFlow(table, '.workbench-table-scroll');
			expect(wrapped.boxScrolls, 'wrapped values need no sideways scrolling').toBe(false);

			await openDisplay(page, `${list.kind}-display-options-toggle`);
			const wrap = page.locator(`#${list.kind}-wrap-values`);
			await expect(wrap).toBeChecked();
			await wrap.uncheck();
			await expect(section).toHaveAttribute('data-table-wrap', 'false');
			const flow = await tableFlow(table, '.workbench-table-scroll');
			expect(flow.whiteSpace.filter(value => value !== 'nowrap'), 'every cell keeps its value on one line')
				.toEqual([]);
			expect(flow.display).toBe('table');
			expect(flow.rowDisplay, 'rows stay table rows, also on a phone').toBe('table-row');
			expect(flow.headVisible).toBe(true);
			expect(flow.boxScrolls, 'the table scrolls sideways in its own box').toBe(true);
			expect(await pageScrollsSideways(page), 'the page itself does not scroll sideways').toBe(false);
			await screenshot(page, `${list.kind}-${width}-scroll`);

			await wrap.check();
			await expect(section).toHaveAttribute('data-table-wrap', 'true');
			expect((await tableFlow(table, '.workbench-table-scroll')).boxScrolls).toBe(false);
		});
	}
}
